const sharedStages = (act: string, chapters: [number, number, number, number]): AudienceChamberItem["stages"] => chamberStages([
  ["alone", "Alone", `When ${act} is entirely unseen, what happens to your willingness and care?`, "It has enough purpose to begin and be done well with no one watching. God's knowledge is enough.", "It still happens, but with less energy or care than when others are there.", "With no one watching, it rarely begins, or loses the part that made it worth doing.", "Name what the deed is for before God, then do one small instance and tell no one.", chapters[0]],
  ["seen", "Seen", `When someone arrives and can see ${act}, what changes in pace, length, polish or visibility?`, "Nothing changes. The person who arrived is no more to you than an animal wandering past.", "It gets a little better or longer, though the first purpose is still alive.", "The audience becomes the real reason it is done, or done well.", "Use Ghazali's curtain test: would you do this if they were behind a curtain? Go back to that measure.", chapters[1]],
  ["praised", "Praised", `When ${act} is praised, what does the praise add, and what do you want next?`, "You ask whether the praise is true. If it is, you thank God for His gift; if not, it grieves you.", "The pleasure lingers and you would like it to happen again.", "The praise becomes the wage, and later deeds are shaped to earn it.", "Name which of the four sweetnesses is at work, and meet it with dislike.", chapters[2]],
  ["overlooked", "Overlooked", `When someone else gets the credit for ${act}, or no one notices it, what remains?`, "The good done is enough. You would be as glad if another were followed instead of you.", "Disappointment comes, but the deed and the friendship stay.", "You stop, resent it, or feel robbed because you were not at the centre.", "Do it again in a way that lets someone else be seen, and stay useful.", chapters[3]],
]);

